def triples_sum_to_zero(l: list):
    n = len(l)
    l.sort()  # Sorting the list to use the two-pointer technique
    for i in range(n - 2):
        left, right = i + 1, n - 1
        while left < right:
            current_sum = l[i] + l[left] + l[right]
            if current_sum == 0:
                return True
            elif current_sum < 0:
                left += 1
            else:
                right -= 1
    return False
