def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100.
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while i * i <= n:
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    primes = [i for i in range(2, 100) if is_prime(i)]

    def find_factors(n, primes, count):
        if count == 0:
            return n == 1
        for prime in primes:
            if prime > n:
                break
            if n % prime == 0:
                if find_factors(n // prime, primes, count - 1):
                    return True
        return False

    return find_factors(a, primes, 3)
