def is_simple_power(x, n):
    if n == 0 and x != 1:
        return False
    if n == 0 and x == 1:
        return True
    if n == 1:
        return x == 1
    if n == -1:
        return x == 1
    if x < 0:
        return False

    base = n
    exponent = 1
    result = base

    while result < x:
        exponent += 1
        result *= base

    return result == x
```

