def count_nums(arr):
    def sum_of_digits(n):
        total = 0
        while n != 0:
            total += n % 10
            n = n // 10
        return total

    def sum_of_signed_digits(n):
        total = 0
        negative = n < 0
        n = abs(n)
        while n != 0:
            digit = n % 10
            if negative and total == 0:
                digit = -digit
            total += digit
            n = n // 10
        return total

    count = 0
    for num in arr:
        if num > 0:
            if sum_of_digits(num) > 0:
                count += 1
        elif num < 0:
            if sum_of_signed_digits(num) > 0:
                count += 1
        else:  # num == 0
            continue

    return count
