def minSubArraySum(nums):
    if not nums:
        return float('inf')

    min_sum = float('inf')
    current_sum = 0
    n = len(nums)

    for i in range(n):
        current_sum = 0
        for j in range(i, n):
            current_sum += nums[j]
            if current_sum < min_sum:
                min_sum = current_sum

    return min_sum
```

