from heapq import heappush, heappop
from collections import deque

def minPath(grid, k):
    N = len(grid)
    directions = [(0, 1), (1, 0), (0, -1), (-1, 0)]

    def is_valid(x, y):
        return 0 <= x < N and 0 <= y < N

    def dijkstra(start):
        pq = [(grid[start[0]][start[1]], start)]
        visited = set()
        min_paths = {start: [grid[start[0]][start[1]]]}

        while pq:
            current_value, (x, y) = heappop(pq)

            if len(min_paths[(x, y)]) == k:
                return min_paths[(x, y)]

            for dx, dy in directions:
                nx, ny = x + dx, y + dy
                if is_valid(nx, ny) and (nx, ny) not in visited:
                    visited.add((nx, ny))
                    next_path = min_paths[(x, y)] + [grid[nx][ny]]
                    min_paths[(nx, ny)] = next_path
                    heappush(pq, (grid[nx][ny], (nx, ny)))

        return []

    min_path = []
    for i in range(N):
        for j in range(N):
            path = dijkstra((i, j))
            if path and (not min_path or path < min_path):
                min_path = path

    return min_path
