def minPath(grid, k):
    from heapq import heappush, heappop

    def dfs(x, y, path, visited):
        if len(path) == k:
            return path

        min_path = None
        for dx, dy in [(-1, 0), (1, 0), (0, -1), (0, 1)]:
            nx, ny = x + dx, y + dy
            if 0 <= nx < len(grid) and 0 <= ny < len(grid[0]) and (nx, ny) not in visited:
                visited.add((nx, ny))
                current_path = dfs(nx, ny, path + [grid[nx][ny]], visited)
                if current_path:
                    if min_path is None or current_path < min_path:
                        min_path = current_path
                visited.remove((nx, ny))
        return min_path

    n = len(grid)
    m = len(grid[0])
    result = None

    for i in range(n):
        for j in range(m):
            visited = set()
            visited.add((i, j))
            current_path = dfs(i, j, [grid[i][j]], visited)
            if current_path:
                if result is None or current_path < result:
                    result = current_path

    return result
