def get_max_triples(n):
    def calculate_value(i):
        return i * i - i + 1

    a = [calculate_value(i) for i in range(1, n + 1)]

    modulo_counts = [0] * 3
    for val in a:
        modulo_counts[val % 3] += 1

    triples_count = 0

    # Case 1: All three numbers are the same modulo 3
    for count in modulo_counts:
        if count >= 3:
            triples_count += (count - 2) * (count - 1) // 2

    # Case 2: Two numbers are the same and the third is different
    if modulo_counts[0] >= 1 and modulo_counts[1] >= 1 and modulo_counts[2] >= 1:
        triples_count += modulo_counts[0] * modulo_counts[1] * modulo_counts[2]

    # Case 3: All three numbers are different
    if modulo_counts[0] >= 2:
        triples_count += modulo_counts[0] * (modulo_counts[0] - 1) // 2
    if modulo_counts[1] >= 2:
        triples_count += modulo_counts[1] * (modulo_counts[1] - 1) // 2
    if modulo_counts[2] >= 2:
        triples_count += modulo_counts[2] * (modulo_counts[2] - 1) // 2

    return triples_count

