    def unique_char_count(word):
        return len(set(word))

    max_unique_count = 0
    result_word = ""

    for word in words:
        count = unique_char_count(word)
        if count > max_unique_count or (count == max_unique_count and word < result_word):
            max_unique_count = count
            result_word = word

    return result_word
```

