def solve(s):
    letters = []
    non_letters = []
    for char in s:
        if char.isalpha():
            letters.append(char.swapcase())
        else:
            non_letters.append(char)
    if letters:
        return ''.join(letters) + ''.join(non_letters)
    else:
        return s[::-1]
